    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base heuristic: Best-Fit (minimize post_residual)
    // We want to minimize the post_residual, but heavily penalize leaving very small gaps 
    // that are unlikely to accommodate future items.
    let mut score = post;

    // Penalty for creating "dead space": gaps smaller than the smallest likely item (10)
    // are highly undesirable unless the item fills the bin perfectly.
    if post > 0.0 && post < 10.0 {
        score += 50.0 * (1.0 - post / 10.0);
    }

    // Dynamic Lookahead coupling: 
    // If the next item is large, prioritize bins that leave enough room for it.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += 15.0 * (1.0 - progress);
        }
    }

    // Adaptive threshold: As the stream progresses, become more aggressive 
    // in packing bins tightly to avoid opening new ones near the end.
    let tightness_factor = 20.0 * progress;
    score += tightness_factor * (mean_residual - post);

    // If this is a new bin (bin_residual == bin_capacity), penalize it based on 
    // how many other bins could have accepted this item.
    if bin_residual == bin_capacity {
        // Only open a new bin if we are forced to or if existing bins are too full
        // to handle the lookahead effectively.
        score += 40.0 + (fitting_bins_count as f64 * 5.0);
    } else {
        // Reward bins that are already open to keep open_bins_count low
        score -= 5.0 * (1.0 / (open_bins_count as f64 + 1.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let post_res = post_residual as f64;

    // Base heuristic: prioritize tight fits
    let mut score = post_res * 0.95;

    // Lookahead: penalize creating a gap smaller than the next item
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size as f64 - post_res) * 5.5;
        } else {
            score -= (post_res - next_item_size as f64) * 0.4;
        }
    }

    // Fragmentation control: penalize small, unusable slivers
    if post_residual > 0 && post_residual < 20 {
        score += 85.0 - (post_res * 2.0);
    }

    if is_new_bin {
        // High cost to open a new bin if others can fit the item
        if fitting_bins_count > 0 {
            score += 280.0 + (open_bins_count as f64 * 18.0) + (progress * 150.0);
        } else {
            // Baseline cost for mandatory new bin
            score = 15.0 + (mean_residual * 0.2);
        }
    } else {
        // Encourage filling bins that are already partially full
        score -= (bin_capacity - bin_residual) as f64 * 0.75;

        // Penalize bins that drift far from the global mean residual
        score += (post_res - mean_residual).abs() * 0.65;
    }

    // Global consolidation: discourage excessive open bins
    if open_bins_count > 3 {
        score += (open_bins_count as f64 - 3.0).powf(1.8) * 25.0;
    }

    // Terminal phase: shift from greedy packing to closure
    if progress > 0.85 {
        score -= (progress - 0.85) * 1200.0;
    }

    // Harmonic bias: favor residuals that are factors of 100 (e.g., 20, 25, 50)
    // This helps match the uniform distribution characteristics of bin packing
    if post_residual > 0 {
        let remainder = post_residual % 20;
        score += (remainder as f64).min(20.0 - remainder as f64) * 1.8;
    }

    // Fitting density bonus: prioritize bins that are "harder" to fit items into
    // to keep highly flexible bins available for larger future items.
    score -= (fitting_bins_count as f64) * 1.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for creating "fragmented" space that is too small for common items.
    // We penalize residuals that fall into the "unusable" range (1-9).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Harmonic Lookahead: If next_item_size is known, prioritize bins that 
    // leave enough space for the next item, or fill the bin perfectly (Best-Fit).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can accommodate the next item (synergy).
            score -= 25.0 * (post_residual as f64 / bin_capacity as f64);
        } else {
            // Penalize bins that would force the next item into a new bin.
            score += 15.0;
        }
    }

    // 3. Density Balancing: Avoid opening new bins unless necessary.
    // If the bin is new, apply a heavy penalty unless the current item fills it very well.
    if bin_residual == bin_capacity {
        score += 40.0;
        // If it's a large item, the penalty for a new bin is lower.
        score -= (item_size as f64) * 0.5;
    }

    // 4. Harmonic thresholding: Favor residuals that are multiples of common item sizes (e.g., 20, 25).
    // This maintains alignment for future packing.
    if post_residual % 20 == 0 {
        score -= 10.0;
    }

    // 5. Global state normalization: If we have many open bins, prioritize closing them 
    // by preferring the tightest fit (Best-Fit logic).
    if open_bins_count > 5 {
        score += post_residual as f64 * 0.2;
    }

    // 6. Final adjustment based on mean residual to avoid "stranded" bins.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
