pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Penalize creating "dead space" that is too small for common items (e.g., < 15)
    // The penalty is non-linear: smaller residuals that are non-zero are highly undesirable.
    let dead_space_penalty = if post_res > 0.0 && post_res < 15.0 {
        (15.0 - post_res).powf(1.5) * 5.0
    } else {
        0.0
    };

    // Reward bins that bring the residual closer to the global mean (balancing load)
    let load_balance_score = (post_res - mean_residual).abs() * 0.5;

    // Lookahead logic: if the next item is large, favor bins with more space
    let lookahead_penalty = if next_item_size > 0 {
        if post_res < next_item_size as f64 {
            (next_item_size as f64 - post_res) * 2.0
        } else {
            0.0
        }
    } else {
        0.0
    };

    // Dynamic threshold: As we approach the end of the stream, discourage opening new bins
    // by inflating the score of empty bins (bin_residual == bin_capacity)
    let is_new_bin = bin_residual == bin_capacity;
    let end_game_penalty = if is_new_bin {
        progress * 50.0
    } else {
        0.0
    };

    // Prefer bins that are the only ones fitting the current item to save others for later
    let scarcity_bonus = if fitting_bins_count == 1 && !is_new_bin {
        -20.0
    } else {
        0.0
    };

    // Base score: prioritize smaller residuals (Best Fit behavior)
    let base_score = post_res;

    base_score + dead_space_penalty + load_balance_score + lookahead_penalty + end_game_penalty + scarcity_bonus
}

