    // Global state awareness: If many bins are open, try to pack into existing ones to reduce open_bins_count.
    // We penalize the new bin option proportionally to the current average fragmentation.
    score += (open_bins_count as f64 * 0.5) * (1.0 - (post_res / bin_capacity as f64));

    // Interaction term: If this is the only bin that fits, give it a significant bonus.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    score
