    let is_new_bin = bin_residual == bin_capacity;
    let post_res = post_residual as f64;

    // Base heuristic: prioritize small post-residuals (Best Fit)
    let mut score = post_res * 1.5;

    // 1. Lookahead & Dead-Space Penalty
    // If we leave space smaller than the next item, we penalize based on the "waste potential"
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 180.0 + (next_item_size as f64 * 2.5);
        } else {
            // Reward space that accommodates the next item
            score -= (post_residual.min(next_item_size) as f64) * 2.2;
        }
    }

    // 2. Dynamic Threshold for New Bin Selection
    if is_new_bin {
        // Only open a new bin if existing bins are suboptimal (high mean residual)
        // or if we have no choice.
        let expansion_cost = 45.0 + (mean_residual * 0.8) + (open_bins_count as f64 * 1.2);
        if fitting_bins_count > 0 {
            // Strong penalty to avoid opening if fits exist
            score = expansion_cost + (fitting_bins_count as f64 * 50.0) * (1.0 - progress);
        } else {
            score = expansion_cost * 0.5;
        }
    } else {
        // 3. Fragmentation Control
        // Penalize residuals that create tiny slivers (hard to fill later)
        if post_residual > 0 && post_residual < 12 {
            score += 60.0;
        }

        // 4. Density Balancing
        // Favor bins that are already well-filled to prioritize them over emptier ones
        score -= (bin_capacity - bin_residual) as f64 * 0.4;

        // 5. Global Consolidation
        // Encourage using existing bins when many are open
        score += (open_bins_count as f64).powf(1.4) * 2.5;
    }

    // 6. Terminal Phase Shift
    // In final stages, force aggressive consolidation
    if progress > 0.85 {
        score -= (progress - 0.85) * 1200.0;
    }

    // 7. Fitting Constraint Reward
    // If a bin is one of the few that can fit this, prioritize it to save space
    if fitting_bins_count < 3 {
