pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // ARCHETYPE: Strict dead space avoidance with bin-count pressure.
    // The goal is to minimize the score, so we penalize small, unusable residuals
    // and provide a dynamic threshold for opening new bins.

    let mut score = post_residual as f64;

    // 1. Dead space penalty: If the post_residual is small (1..9), it is likely "unusable" 
    // because the minimum item size is 10. Heavily penalize these gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 100.0 / (post_residual as f64);
    }

    // 2. Open bins pressure: As the number of open bins increases, we become more
    // aggressive about filling existing bins, even if the fit is suboptimal.
    score += (open_bins_count as f64) * 0.5;

    // 3. Lookahead optimization: If the next item is large, favor keeping space for it
    // in bins that currently have enough room.
    if next_item_size > 0 && next_item_size > post_residual {
        score += 20.0;
    }

    // 4. New bin logic: When bin_residual == bin_capacity, we are evaluating a new bin.
    // We only want to open a new bin if the existing options are all "bad" (i.e., they
    // create unusable dead space).
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin is high to encourage packing.
        // We reduce this cost if we have many bins open or if the current packing is inefficient.
        score = 65.0 + (open_bins_count as f64 * 0.1);
    } else {
        // If we are placing into an existing bin, we reward placements that leave 
        // the bin "nearly full" (residual 0) or "very roomy" (residual > 20).
        if post_residual == 0 {
            score -= 15.0;
        } else if post_residual >= 20 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score. 
    // Best Fit Decreasing (BFD) logic is embedded by rewarding smaller post_residual.
    // We introduce harmonic penalties to avoid "orphaned" small residuals that cannot fit future items.

    let mut score = post_residual as f64;

    // Harmonic Penalty: Penalize residuals that are too small to fit common item sizes (e.g., < 20).
    // If the post_residual is in the range [1, 19], it is highly likely to be wasted space.
    if post_residual > 0 && post_residual < 20 {
        score += 40.0 * (20.0 - post_residual as f64) / 20.0;
    }

    // Lookahead Integration: If the next item is large, favor bins that can accommodate it.
    if next_item_size > 0 && next_item_size > post_residual {
        score += 30.0; // Penalty for placing current item if it blocks the next one from fitting here
    }

    // Fitting Bins Constraint: If this is the only bin that fits the current item, 
    // it is usually better to take it than to open a new bin, unless the fit is catastrophic.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0; // Strong incentive to use the last available bin
    }

    // New Bin Threshold: If we are considering a new bin (bin_residual == bin_capacity),
    // only accept it if the current best open bin results in a very poor fit (post_residual < 10).
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0;
        } else {
            // New bin is expensive. Only open if the current average residual is already high
            // or if we have many bins open and fragmentation is likely.
            score = 45.0 + (mean_residual * 0.5);
        }
    }

    // Progress scaling: As the stream nears the end, become more aggressive in packing
    // to minimize the trailing open bins.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score: punish large post_residuals (Best Fit logic)
    let mut score = post_res;

    // Penalty for creating "dead zones" (small residuals that are hard to fill)
    // We target a residual of 0 or a value likely to fit the lookahead item
    if post_res > 0.0 {
        let lookahead_penalty = if next_item_size > 0 && post_res < next_item_size as f64 {
            // If the lookahead item won't fit, penalize exponentially based on how much space is wasted
            (next_item_size as f64 - post_res).powf(1.5)
        } else {
            0.0
        };
        score += lookahead_penalty;
    }

    // Dynamic weighting based on stream progress: 
    // Early on, be greedy (pack tight). Near the end, be more permissive to close bins.
    let tightness_factor = 1.0 + (progress * 2.0);
    score *= tightness_factor;

    // If this is the only bin that fits, prioritize it heavily by reducing the score
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // If considering a new bin, penalize it relative to the average remaining space
    if bin_residual == bin_capacity {
        // New bin cost is high, but decreases as we approach the end of the stream
        // to prevent leaving items stranded.
        score += (mean_residual * 0.5) + (1.0 - progress) * 40.0;
    } else {
        // Reward bins that bring the mean residual closer to a desired equilibrium
        // where we aim for bins to be nearly full.
        score += (mean_residual - post_res).abs() * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
