    }

    // 4. Strategic new-bin threshold
    // If this is a new bin (bin_residual == bin_capacity), penalize it heavily unless fitting_bins_count is low
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily discourage opening a new bin if other options exist
            score += 60.0 + (fitting_bins_count as f64 * 10.0);
        } else {
            // If no other options, normalize the new bin score to be competitive
            score = 40.0;
        }
    }

    // 5. Progression awareness: As we near the end of the stream, prioritize tight packing
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

