            score += 25.0 * (1.0 - progress);
        }
    }

    // 2. Fragment Avoidance:
    // Increased penalty for small "dead" residuals that are harder to fill.
    if post_residual > 0 && post_residual < 22 {
        score += (22.0 - post_residual as f64) * 2.8;
    }

    // 3. New Bin Cost Function:
    // Refined thresholding to prevent premature bin opening.
    if is_new_bin {
        if fitting_bins_count > 0 {
