        // Penalize larger post_residuals for existing bins, scaled by density.
        score += (post_residual as f64 * 0.6) / (1.0 + (fitting_bins_count as f64 * 0.1));
    }

    // 5. Global Consolidation Pressure:
    // Use a sharper growth penalty for open bins to keep the count low.
    if open_bins_count > 3 {
