    }

    // 7. Residual Variance Dampening:
    // Keep bin levels uniform to improve future packing density.
    let deviation = (bin_residual as f64 - mean_residual).abs();
    if !is_new_bin {
        score += deviation * 0.08;
    }

    // Final temporal adjustment:
    // Favor tighter packing towards the end of the stream.
    score -= progress * 15.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
