    // We want to minimize this (Best Fit principle).
    let mut score = post_residual as f64;

    // Penalty for creating "slivers" (very small, hard-to-fill residuals).
    // If post_residual is small but > 0, it's often worse than leaving it empty.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // Lookahead logic: if we have a next item, try to ensure this bin can fit it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can accommodate the next item (synergy).
            score -= 15.0;
        } else {
            // Penalize if this placement prevents the next item from fitting here.
            score += 5.0;
        }
    }

    // Global state awareness: 
    // If the bin is a new bin (bin_residual == bin_capacity), penalize opening it
    // unless the mean residual of current bins is already very tight.
    if bin_residual == bin_capacity {
        score += 30.0; // Base cost to open a new bin.
        // As we progress through the stream, be more conservative about opening new bins.
        score += 20.0 * progress;
        // If we have many open bins already, make opening a new one more expensive.
        score += (open_bins_count as f64) * 2.0;
    }

    // Dynamic adaptation: 
    // If fitting_bins_count is low, we are running out of options for this item.
    // Reduce the penalty for the current bin to ensure we don't open a new one unnecessarily.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Adjust based on mean_residual: if current bins are very full, 
    // prioritize keeping the mean high by filling current bins effectively.
    if mean_residual < 20.0 {
        score -= 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

