    let mut score = post_residual as f64;

    // 1. Predictive Lookahead:
    // If the bin leaves a residual smaller than the next item, we create a dead-space trap.
    // We scale the penalty by the ratio of the gap to the next item size.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 95.0 + (next_item_size as f64 - post_residual as f64) * 1.5;
        } else if post_residual >= next_item_size {
            // Reward "perfect" residual alignment for the next expected item.
            score -= ((post_residual - next_item_size) as f64).min(20.0) * 1.2;
        }
    }

    // 2. Harmonic Fragmentation Avoidance:
    // Penalize small residual fragments that are notoriously hard to fill.
    if post_residual > 0 && post_residual < 25 {
        score += (25.0 - post_residual as f64).powf(1.8) * 3.5;
    }

    // 3. Dynamic Bin Management:
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Aggressive consolidation: exponentially penalize opening new bins if alternatives exist.
            score += 250.0 + (open_bins_count as f64 * 8.0) + (progress * 100.0);
        } else {
            // Baseline for unavoidable expansion.
            score = 50.0 + (mean_residual * 0.2);
        }
    } else {
        // 4. Density Balancing:
        // Reward bins that have high usage (low residual).
        score -= (bin_capacity - bin_residual) as f64 * 0.6;

        // Penalize deviation from the mean to encourage uniform filling.
        score += (post_residual as f64 - mean_residual).abs() * 0.4;
    }

    // 5. Global Consolidation:
    // Non-linear penalty on open bin count to force compaction.
    if open_bins_count > 1 {
        score += (open_bins_count as f64).powf(1.75) * 12.0;
    }

    // 6. Terminal Phase Shift:
    // Increased pressure to close bins as we approach the end of the stream.
    if progress > 0.75 {
        score -= (progress - 0.75) * 300.0;
    } else {
        score -= progress * 15.0;
    }

    // 7. Modulo Bias:
    // Encourage residuals that are multiples of 25, statistically common for item distributions.
    score += ((post_residual % 25) as f64) * 0.5;

    // 8. Fitting Constraint:
    // If this bin is the last one that can fit the current item, prioritize it strongly.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
