pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize small residuals that are likely to become stranded (dead space)
    // We create a non-linear "valley" where residuals near 10-15 are heavily penalized
    // unless it is the very end of the stream.
    let dead_space_penalty = if post > 0.0 && post < 15.0 {
        (15.0 - post).powi(2) * (1.0 - progress) * 2.0
    } else {
        0.0
    };

    // Lookahead logic: If the next item is large and won't fit in the remaining space,
    // we want to preserve larger residuals now.
    let lookahead_pressure = if next_item_size > post_residual && next_item_size > 0 {
        (next_item_size - post_residual) as f64 * 0.5
    } else {
        0.0
    };

    // Favor filling bins that are already "half-empty" to keep the mean_residual stable
    let density_balance = (post - mean_residual).powi(2) * 0.1;

    // Discourage opening a new bin prematurely unless the current fit is poor
    let new_bin_bias = if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            0.0 // Necessary
        } else {
            // Penalize opening a new bin significantly unless items are very large
            (item_size as f64 * 1.5) + (open_bins_count as f64 * 5.0)
        }
    } else {
        0.0
    };

    // Combine: Lower score is better. 
    // We prioritize the Best Fit (post_residual) but modulate with stream progress and lookahead.
    post + dead_space_penalty + lookahead_pressure + density_balance + new_bin_bias
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
