            score += 145.0 + (next_item_size as f64 * 1.8);
        } else if post_residual >= next_item_size {
            // Reward bins that leave a residual perfectly aligned with next_item_size.
            let diff = (post_residual - next_item_size) as f64;
            score -= (1.0 / (1.0 + diff)) * 65.0 + (diff * 0.6);
        }
    }

    // 2. Harmonic Fragmentation Avoidance:
    // Focus on the "cliff" of small residuals where packing efficiency drops.
    if post_residual > 0 && post_residual < 22 {
        score += 128.0 - (post_residual as f64 * 2.8);
    }

    // 3. Dynamic Bin Management:
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Heavier penalty for opening new bins when existing ones can accommodate.
            score += 345.0 + (open_bins_count as f64 * 14.0) + (progress * 125.0);
        } else {
            score = 20.0 + (mean_residual * 0.22);
        }
    } else {
        // 4. Density Balancing & Closing:
        // Favor bins nearing full capacity to accelerate closure.
        score -= (bin_capacity - bin_residual) as f64 * 0.92;

        // Deviation penalty: maintain uniform bin filling to avoid "outlier" bins.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 1.1;
    }

    // 5. Global Consolidation:
    // Exponential penalty on open bin count.
    if open_bins_count > 1 {
        score += (open_bins_count as f64).powf(2.05) * 18.0;
    }

    // 6. Terminal Phase Shift:
    // In the final stages, prioritize filling existing bins to minimize total count.
    let terminal_multiplier = if progress > 0.75 { 550.0 } else { 55.0 };
    score -= (progress * terminal_multiplier);

    // 7. Residual Modulo Bias:
    // Encourage residuals that are multiples of 10 or 25 to reduce fragmentation.
    let mod_10 = (post_residual % 10) as f64;
    let mod_25 = (post_residual % 25) as f64;
    score += (mod_10.min(10.0 - mod_10) * 1.5) + (mod_25.min(25.0 - mod_25) * 0.8);

    // 8. Bin Saturation Bonus:
    // If the bin is nearly full (post_residual < 4), give a massive reward to finish it.
    if post_residual < 4 {
        score -= 95.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let is_new_bin = bin_residual == bin_capacity;
