    let mut score = post_residual as f64;

    // 1. Fragment Avoidance:
    // Penalize gaps that are too small to be useful (1-18).
    // The penalty is non-linear to discourage "orphaned" small space.
    if post_residual > 0 && post_residual < 19 {
