    if next_item_size > 0 && post_residual < next_item_size {
        score += 150.0 + (next_item_size as f64 * 1.5);
    }

    // 3. New Bin Handling:
    // If we are considering a new bin, only do so if existing bins are poor fits.
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if an existing one can hold the item.
            // Scale with open_bins_count to prevent runaway bin creation.
            score += 450.0 + (open_bins_count as f64 * 15.0) + (progress * 120.0);
        } else {
            // The only way to accept an item if no bins fit is to open a new one.
            score = 10.0 + (mean_residual * 0.5);
        }
    } else {
        // 4. Existing Bin Optimization:
        // Reward filling bins to capacity (lower post_residual).
        // Penalize deviation from mean_residual to keep bins balanced.
        score -= (bin_capacity - bin_residual) as f64 * 0.4;
        score += (post_residual as f64 - mean_residual).abs() * 0.95;

        // If this is the last fitting bin, prioritize it to prevent opening a new one later.
        if fitting_bins_count == 1 {
            score -= 120.0;
        }
    }

    // 5. Global Consolidation:
    // Discourage high open bin counts relative to the total items processed.
    if open_bins_count > 5 {
        score += (open_bins_count as f64 * 5.0).powf(1.5);
    }

    // 6. Terminal Phase:
    // In the final 10% of the stream, prioritize closing bins at all costs.
    if progress > 0.9 {
        score -= (progress - 0.9) * 1000.0;
    }

    // 7. Harmonic Alignment:
    // Encourage residuals that align with common item size patterns (multiples of 10).
    let alignment = post_residual % 10;
    score += (alignment as f64).min(10.0 - alignment as f64) * 2.0;

    score
}

