    // Penalize gaps that trap the next item (Dead-space avoidance).
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 195.0 + (next_item_size as f64 * 2.8);
        } else if post_residual >= next_item_size {
            // Reward bins that leave space for the next item, adjusted for global density.
            score -= ((post_residual - next_item_size) as f64).sqrt() * 6.2;
        }
