    // 2. Harmonic Fragmentation Avoidance:
    // Aggressively penalize micro-fragments (1-24) to prevent unusable slivers.
    if post_residual > 0 && post_residual < 24 {
        score += 165.0 - (post_residual as f64 * 4.2);
    }

    // 3. Dynamic Bin Management:
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Force reuse of existing bins: penalty scales with open_bins_count and progress.
            score += 340.0 + (open_bins_count as f64).powf(1.6) * 18.0 + (progress * 150.0);
        } else {
            // New bin baseline: reduced to allow necessary expansion.
            score = 22.0 + (mean_residual * 0.25);
        }
    } else {
        // 4. Density Balancing:
        // Favor closing bins that are nearly full (higher bin_capacity - bin_residual).
        score -= (bin_capacity - bin_residual) as f64 * 1.15;

        // Penalize deviation from the mean to keep bin states consolidated.
        score += (post_residual as f64 - mean_residual).abs() * 1.05;
    }

    // 5. Global Consolidation:
    // Strong non-linear penalty to prevent runaway bin opening.
    if open_bins_count > 2 {
        score += (open_bins_count as f64 - 2.0).powf(2.2) * 42.0;
    }

    // 6. Terminal Phase Shift:
    // In the final 25%, prioritize packing existing bins regardless of residual quality.
    if progress > 0.75 {
        score -= (progress - 0.75) * 800.0;
    } else {
        score -= progress * 60.0;
    }

    // 7. Residual Modulo Bias:
    // Favor residuals that align with common item size clusters (20, 25).
    let mod_val = post_residual % 25;
    score += (mod_val as f64).min(25.0 - mod_val as f64) * 2.5;

    score
}

