    // 2. Fragment Avoidance:
    // Penalize small, unusable gaps. 1-22 is the critical range for 100-capacity bins.
    if post_residual > 0 && post_residual < 23 {
        score += 165.0 - (post_residual as f64 * 3.2);
    }

    // 3. Dynamic Bin Management:
    if is_new_bin {
