            score = 15.0 + (mean_residual * 0.25);
        }
    } else {
        // 4. Density Balancing:
        // Reward bin utilization and discourage excessive fragmentation relative to mean.
        score -= (bin_capacity - bin_residual) as f64 * 0.95;
        score += (post_residual as f64 - mean_residual).abs() * 0.85;

        // Prioritize "closing" bins that are nearly full.
        if post_residual < 10 {
