    // 7. Harmonic Alignment:
    // Favor residuals that are multiples of 20 to keep remaining space clean for future items.
    let mod_val = post_residual % 20;
    score += (mod_val as f64).min(20.0 - mod_val as f64) * 1.5;

    // 8. Crowding avoidance:
    // If many bins fit this item, prefer the one that is currently the least "crowded" 
