    let is_new_bin = bin_residual == bin_capacity;

    // Base score: Linear cost for residual, weighted to favor tight packing.
    // Increased reliance on post_residual to minimize wasted space.
    let mut score = (post_residual as f64) * 1.32;

    // 1. Predictive Lookahead:
    // Tightened penalty for dead-space traps; aggressive reward for perfect fit.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 225.0 + (next_item_size as f64 * 2.4);
        } else if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 2.10;
        }
    }

    // 2. Harmonic Fragmentation Avoidance:
    // Penalize small fragments more aggressively to prevent bin pollution.
    if post_residual > 0 && post_residual < 35 {
        score += 165.0 - (post_residual as f64 * 3.3);
    }

    // 3. Dynamic Bin Management:
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Force reuse of existing bins: scale penalty with open_bins_count and progress.
            // Added quadratic growth factor for high bin count to prevent fragmentation.
            score += 345.0 + (open_bins_count as f64).powf(1.8) * 16.0 + (progress * 150.0);
        } else {
            // Baseline for expansion: optimized to keep new bins competitive only when necessary.
            score = 18.0 + (mean_residual * 0.12);
        }
    } else {
        // 4. Density Balancing:
        // Reward filling bins to capacity to trigger consolidation.
        score -= (bin_capacity - bin_residual) as f64 * 0.98;

        // Penalize deviation from the mean to encourage uniformity.
        score += (post_residual as f64 - mean_residual).abs() * 0.92;
    }

    // 5. Global Consolidation:
    // Non-linear penalty on open bin count.
    if open_bins_count > 2 {
        score += (open_bins_count as f64 - 2.0).powf(2.25) * 42.0;
    }

    // 6. Terminal Phase Shift:
    // Accelerate consolidation in the final 20% of the stream.
    if progress > 0.80 {
        score -= (progress - 0.80) * 1100.0;
    } else {
        score -= progress * 65.0;
    }

    // 7. Residual Modulo Bias:
    // Favor residuals that are multiples of 20/25 to reduce fragmentation.
    let mod_val = post_residual % 20;
    score += (mod_val as f64).min(20.0 - mod_val as f64) * 2.8;

    // 8. Fitting Capacity Bonus:
    // Favor bins that are more constrained to increase packing density.
    // Negative correlation with fitting_bins_count to prioritize "hard-to-fit" bins.
    score -= (fitting_bins_count as f64) * 0.85;

    score
}

