    let mut score = post_residual as f64;

    // 1. New Bin Penalty: If this is an existing bin, favor it over a new bin.
    // If it's a new bin, apply a significant penalty to force using existing bins unless the fit is perfect.
    if bin_residual == bin_capacity {
        score += 45.0; 
