    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    // 5. Urgency: As the stream progresses, favor packing tighter to avoid 
    // trailing bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    // 6. Last Chance Logic: If this is the only bin that can fit the item, 
    // strongly incentivize using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
