    // 2. Lookahead mechanism: If a future item exists, prefer bins where the next item fits well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can accommodate the next item perfectly (residual near 0).
            let future_fit_rem = (post_residual - next_item_size) as f64;
            score -= (100.0 - future_fit_rem) * 0.5;
        } else {
            // Penalize if the next item will force a new bin because this one is too full.
            score += 15.0;
        }
    }

    // 3. Global state: If we are near the end of the stream, prioritize closing bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && post_residual < 10 {
        score -= 20.0;
    }

    // 4. New Bin Handling:
    // If this is a new bin (bin_residual == bin_capacity), make it expensive unless no other bin fits well.
    if bin_residual == bin_capacity {
        score += 45.0;
        // If it's the only option, reduce the penalty.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // 5. Balance open bins:
    // If we have many bins open, penalize creating new ones further.
    if open_bins_count > (total_items / 20).max(5) {
        score += (open_bins_count as f64) * 0.2;
    }

    score
}

