    let is_new_bin = bin_residual == bin_capacity;

    // Base score: Refined residual penalty for tighter packing.
    let mut score = (post_residual as f64) * 1.35;

    // 1. Predictive Lookahead:
    // Enhanced penalty for dead-space traps; reward for residuals near next_item_size.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 245.0 + (next_item_size as f64 * 2.4);
        } else if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 2.15;
        }
    }

    // 2. Harmonic Fragmentation Avoidance:
    // Increased penalty for small fragments to force deeper consolidation.
    if post_residual > 0 && post_residual < 35 {
        score += 180.0 - (post_residual as f64 * 3.8);
    }

    // 3. Dynamic Bin Management:
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Non-linear penalty for new bin usage, accelerated by open_bins_count.
            score += 385.0 + (open_bins_count as f64).powf(1.8) * 18.0 + (progress * 150.0);
        } else {
            score = 15.0 + (mean_residual * 0.12);
        }
    } else {
        // 4. Density Balancing:
        // Reward filling bins towards capacity; increase penalty for deviation from the global mean.
        score -= (bin_capacity - bin_residual) as f64 * 1.05;
        score += (post_residual as f64 - mean_residual).abs() * 1.15;
    }

    // 5. Global Consolidation:
    // Higher order penalty to suppress bin proliferation in middle-to-late game.
    if open_bins_count > 3 {
        score += (open_bins_count as f64 - 3.0).powf(2.3) * 45.0;
    }

    // 6. Terminal Phase Shift:
    // Aggressive consolidation in the final 25% of the stream.
    if progress > 0.75 {
        score -= (progress - 0.75) * 1250.0;
    } else {
        score -= progress * 40.0;
    }

    // 7. Residual Modulo Bias:
    // Favor residuals that align with capacity constraints (multiples of 10/25).
    let mod_val = post_residual % 25;
    score += (mod_val as f64).min(25.0 - mod_val as f64) * 2.8;

    // 8. Fitting Capacity Bonus:
    // Discourage opening new bins by rewarding bins that have higher fitting potential.
    score -= (fitting_bins_count as f64).sqrt() * 5.5;

    score
}

