    }

    // 3. Balancing: Avoid opening new bins too early unless the fit is excellent.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Only open a new bin if the current mean_residual is already very low (tightly packed)
        // or if we have no good options.
        if mean_residual > 20.0 {
            score += 40.0;
        } else {
            score += 15.0;
        }
    }

    // 4. Pressure: As the stream progresses, become more conservative about opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if is_new_bin {
        score += progress * 20.0;
    }

    // 5. If this is the only bin that fits the current item, prioritize it heavily.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
