pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Penalize small residuals that create "dead space" (unusable gaps < 10)
    // We reward post_residual values that are either 0 (perfect fit) or large enough to accommodate future items.
    let dead_space_penalty = if post_res > 0.0 && post_res < 10.0 {
        100.0 / post_res
    } else {
        0.0
    };

    // Use lookahead to penalize bins that leave a gap smaller than the next item
    let lookahead_penalty = if next_item_size > 0 && post_res < next_item_size as f64 {
