    // Strategy: Prefer Best-Fit (minimizing post_residual) early on, 
    // but shift to First-Fit/New-Bin logic as the stream progresses to keep bins "open" for large items.
    // We normalize the influence of the residual based on progress.
    let base_score = post_res + (dead_space_penalty * (1.0 - progress)) + (lookahead_penalty * (0.5 + progress));

    // If this is a new bin (bin_residual == bin_capacity), apply a bias.
    // We only want to open a new bin if the existing fits are objectively poor (high residuals).
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_bias = if is_new_bin {
        // Only open new if we have many bins or if the mean residual is already quite low (suggesting we are wasting space)
        // or if the current fitting bins are forced to create "bad" residuals.
        30.0 + (mean_residual * 0.5) - (progress * 10.0)
    } else {
        0.0
    };

    base_score + new_bin_bias
}

