        }
    }

    // 4. Threshold for opening a new bin:
    // If this is a new bin (bin_residual == bin_capacity), penalize based on 
    // current open bins count to prevent premature bin explosion.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 5.0;
