        if fitting_bins_count > 0 {
            score += 30.0;
        }
    }

    // 5. Global efficiency: If the current bin's residual is significantly better 
    //    than the mean, prioritize it to keep the mean residual low.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // 6. Progress factor: Be more conservative with new bins as we reach the end of the stream
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += (1.0 - progress) * 10.0;
