    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post_residual (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for opening a new bin:
    // As the stream progresses, we become more conservative about opening new bins.
    if is_new_bin {
        score += 15.0 + (progress * 45.0);
    }

    // Heuristic: Prefer bins that leave space for the next item (Lookahead optimization)
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize placements that block the next item from fitting in this bin
            score += 25.0 * (1.0 - progress);
        } else {
            // Reward placements that leave exactly enough or slightly more room for the next item
            let waste = (post_residual - next_item_size) as f64;
            score -= (10.0 / (1.0 + waste)) * (1.0 - progress);
        }
    }

    // Heuristic: Avoid fragmentation (Best Fit / Tightening)
    // If we have many fitting bins, we want the one that results in the smallest post_residual
    // to keep others open for potentially larger items.
    if fitting_bins_count > 1 && !is_new_bin {
        // Penalize bins that leave a "dead zone" (e.g., 1-9 residual) if we are late in the stream
        if post_residual > 0 && post_residual < 10 {
            score += 20.0 * progress;
        }
    }

    // Heuristic: Global state balancing
    // If the mean residual of current bins is high, prefer bins that reduce that mean
    if mean_residual > (bin_capacity as f64 * 0.3) && post_residual < (mean_residual as u32) {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Core structural heuristic: prioritize tight fits while penalizing dead-space traps
    let mut score = (post_residual as f64) * 1.35;

    // 1. Adaptive Lookahead:
    // Aggressively penalize residuals that are smaller than the next item to prevent fragmentation.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 245.0 + (next_item_size as f64 * 2.8);
        } else if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 2.15;
        }
    }

    // 2. Non-linear Fragmentation Penalty:
    // Use a sigmoid-like curve to penalize mid-sized residuals that cannot fit common items.
    if post_residual > 0 && post_residual < 40 {
        score += (40.0 - post_residual as f64).powf(1.4) * 4.2;
    }

    // 3. Dynamic Expansion Control:
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Exponential pressure to reuse existing bins, especially as stream progresses
            score += 380.0 + (open_bins_count as f64).powf(1.8) * 16.5 + (progress * 210.0);
        } else {
            // Minimal cost for opening a new bin when no current bin can fit the item
            score = 12.0 + (mean_residual * 0.22);
        }
    } else {
        // Density Balancing: Reward bins that are approaching capacity
        score -= (bin_capacity - bin_residual) as f64 * 1.15;
        // Penalize deviation from the global mean to enforce uniform packing
        score += (post_residual as f64 - mean_residual).abs() * 1.12;
    }

    // 4. Global Consolidation Pressure:
    // Non-linear penalty on open bin count increases as we approach the end of the stream
    if open_bins_count > 1 {
        score += (open_bins_count as f64).powf(2.25) * 45.0 * (1.0 + progress);
    }

    // 5. Terminal Phase Optimization:
    // Shift strategy from "local packing" to "global completion"
    if progress > 0.85 {
        score -= (progress - 0.85) * 1200.0;
    }

    // 6. Harmonic Residual Bias:
    // Bias toward residuals that are factors of bin_capacity (typically 100) to simplify future fit
    let rem = post_residual % 20;
    score += (rem as f64).min(20.0 - rem as f64) * 3.2;

    // 7. Fitting Capacity Multiplier:
    // Reward bins that have few options for future items to "burn" them early
    score -= (fitting_bins_count as f64).powf(0.85) * 1.25;

    score
}

