    // 2. Harmonic Class Awareness:
    // If post_residual is a small divisor of capacity, it creates "unusable" gaps for large items.
    // We heavily penalize post_residual values that are too small to fit common item sizes (e.g., < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0; 
    }

    // 3. Lookahead Logic:
    // If the next item is large, we want to prioritize bins that can accommodate it.
    // If the next_item_size fits in the current post_residual, we reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 4. Scarcity/Bin Management:
    // If this is the only bin that can fit the item, we must take it to avoid opening a new one unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 100.0;
    }

    // 5. New Bin Penalty:
    // If the bin is new (bin_residual == bin_capacity), penalize it unless no other bin fits.
    if bin_residual == bin_capacity {
        score += 60.0;
        // If we are near the end of the stream, opening a new bin is relatively more expensive.
        score += (step_index as f64 / total_items as f64) * 20.0;
    }

    // 6. Mean Residual Balancing:
    // Avoid bins that deviate significantly from the mean residual to prevent fragmented bin states.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.5;

    score
}

