    // post_residual represents the "wastage" if we place the item here.
    // We want to minimize wastage but avoid fragmenting space in a way that prevents future fits.

    let mut score = post_residual as f64;

    // 1. Penalize creating very small, unusable fragments (1-9 space left is usually dead weight).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Lookahead logic: If the next item fits into the current post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // 3. Global State: If we are near the end of the stream, prioritize filling existing bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (1.0 - progress) * 50.0;
    }

    // 4. Fitting constraints: If this is the only bin that fits the current item, prioritize it strongly.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // 5. New Bin Threshold: If this is a new bin (bin_residual == bin_capacity), 
    // only choose it if the current fit is truly terrible (high post_residual).
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin unless we have many open bins already or the item is large.
        score += 30.0 + (open_bins_count as f64 * 0.5);
    } else {
        // Encourage balanced filling: reward bins that stay close to the mean_residual of other bins.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: Linear cost for residual, weighted to favor tight packing.
    // Adjusted weight to balance against the lookahead penalty.
    let mut score = (post_residual as f64) * 1.35;

    // 1. Predictive Lookahead:
    // Increased penalty for dead-space traps; increased reward for perfect fit.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 265.0 + (next_item_size as f64 * 3.2);
        } else if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 2.35;
        }
    }

    // 2. Harmonic Fragmentation Avoidance:
    // Penalize small fragments more aggressively to prevent bin pollution.
    if post_residual > 0 && post_residual < 28 {
        score += 190.0 - (post_residual as f64 * 5.5);
    }

    // 3. Dynamic Bin Management:
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Force reuse of existing bins: scale penalty with open_bins_count and progress.
            score += 450.0 + (open_bins_count as f64).powf(1.9) * 22.0 + (progress * 180.0);
        } else {
            // Baseline for expansion: optimized to keep new bins competitive only when necessary.
            score = 12.0 + (mean_residual * 0.10);
        }
    } else {
        // 4. Density Balancing:
        // Reward filling bins to capacity to trigger consolidation.
        score -= (bin_capacity - bin_residual) as f64 * 1.25;

        // Penalize deviation from the mean to encourage uniformity.
        score += (post_residual as f64 - mean_residual).abs() * 1.05;
    }

    // 5. Global Consolidation:
    // Non-linear penalty on open bin count to prevent runaway bin proliferation.
    if open_bins_count > 3 {
        score += (open_bins_count as f64 - 3.0).powf(2.4) * 55.0;
    }

    // 6. Terminal Phase Shift:
    // Accelerate consolidation in the final 20% of the stream.
    if progress > 0.85 {
        score -= (progress - 0.85) * 1300.0;
    } else {
        score -= progress * 40.0;
    }

    // 7. Residual Modulo Bias:
    // Favor residuals that are multiples of 25 to reduce fragmentation.
    let mod_val = post_residual % 25;
    score += (mod_val as f64).min(25.0 - mod_val as f64) * 3.8;

    // 8. Fitting Capacity Bonus:
    // Favor bins that are more constrained to increase packing density.
    // Enhanced weight to prioritize closing off nearly full bins.
    score -= (fitting_bins_count as f64) * 2.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining space (Best Fit principle).
    let mut score = post;

    // Penalty for leaving small, unusable slivers of space (fragmentation).
    // If post_residual is small but not zero, it's highly inefficient.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - progress);
    }

    // Lookahead coupling: If the next item is large, favor bins that can accommodate it.
    // If post_residual is too small to fit next_item_size, we penalize the current choice.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 25.0 * (1.0 - progress);
        }
    }

    // Dynamic threshold: As the stream progresses, become more aggressive in packing
    // tightly to avoid opening new bins late in the sequence.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // Last chance to fit in an existing bin, heavily discount the score.
        score -= 40.0 * (1.0 + progress);
    }

    // New bin logic: penalize opening a new bin unless the current fit is extremely poor.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin increases as the stream progresses.
        score += 60.0 + (40.0 * progress);

        // If there are many open bins, we should try to use them rather than opening new ones.
        score += (open_bins_count as f64) * 2.0;
    }

    // Balance against the mean residual to encourage uniform bin usage.
    score += (post - mean_residual).abs() * 0.5;

    score
}

