    score += (post_residual as f64).powf(1.5);

    // 2. Harmonic Class logic: If the current item leaves a gap that is a poor fit for common divisors,
    // penalize it. We want to preserve space for potential next items.
    if next_item_size > 0 {
        // If the current post_residual is smaller than the next item, this bin becomes a "dead" bin for the next step.
        // We heavily penalize creating small, unusable gaps.
