    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if we have fitting alternatives.
            score += 200.0 + (open_bins_count as f64 * 10.0);
        } else {
            // If no bins fit, opening a new bin is mandatory; set a neutral base.
            score = 50.0;
