    // 4. Mean Residual Balancing:
    // Avoid creating bins that are significantly below the current mean_residual, 
    // as this suggests we are fragmenting our bin space.
    if (post_residual as f64) < mean_residual * 0.5 {
        score += 30.0;
    }

    // 5. Progression scaling:
    // Toward the end of the stream, prioritize closing bins (minimizing open_bins_count).
    let progress = step_index as f64 / total_items as f64;
    score += progress * (open_bins_count as f64 * 5.0);

    score
}

