        // Stronger reward for filling, but modulated by the remaining capacity to favor tightest fit.
        score -= (bin_capacity - bin_residual) as f64 * 1.15;

        // Penalize variance from global mean to minimize bin-size dispersion.
        score += (post_residual as f64 - mean_residual).abs() * 1.05;
    }

    // 5. Global Consolidation:
    // Penalty for open bin count grows faster to force closure of low-density bins.
    if open_bins_count > 1 {
        score += (open_bins_count as f64 - 1.0).powf(2.35) * 45.0;
    }

    // 6. Terminal Phase Shift:
    // Aggressive consolidation in the final 15% of the stream.
    if progress > 0.85 {
        score -= (progress - 0.85) * 1200.0;
    } else {
        score -= progress * 40.0;
    }

    // 7. Residual Modulo Bias:
    // Reward residuals that maximize future fitting combinations (multiples of 20).
    let mod_val = post_residual % 20;
    score += (mod_val as f64).min(20.0 - mod_val as f64) * 2.8;

    // 8. Fitting Capacity Bonus:
    // Favor bins that are more constrained to increase packing density.
    score -= (fitting_bins_count as f64) * 0.95;

    // 9. Overflow Protection:
    // Penalize extreme under-filling.
    if post_residual > (bin_capacity / 2) {
        score += (post_residual as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
