    let balance_factor = (post_res - mean_residual).abs() * 0.5;

    // Lookahead: If next_item_size is large, penalize small post_residuals 
    // that won't fit the next item.
    let lookahead_penalty = if next_item_size > post_residual && post_residual > 0 {
        (next_item_size as f64 - post_res) * 0.8
    } else {
