pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Minimize post_residual, but heavily penalize 
    // creating "unusable" small gaps (1-9) that are hard to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // 2. Lookahead Awareness: If the next item fits into the post_residual,
    // reward this bin heavily to create a "perfect pair".
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 * (1.0 - (post_residual - next_item_size) as f64 / 100.0);
    }

    // 3. Global Efficiency: If we have many open bins, prioritize tighter fills.
    // If we are nearing the end of the stream, prioritize clearing bins (lower residual).
    let open_bins_factor = (open_bins_count as f64).sqrt();
    score += open_bins_factor * 2.0;

    // 4. New Bin Logic: If bin_residual == bin_capacity, we are evaluating a new bin.
    // Only open a new bin if we have many open bins already or if the fit quality 
    // of all existing bins is poor (high mean_residual).
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0;
        } else {
            // Threshold for opening a new bin: only if mean_residual is high
            // and we aren't at the very end of the stream.
            score = 50.0 + (mean_residual * 0.5) - (progress * 20.0);
        }
    } else {
        // 5. Scarcity Penalty: If this is the only bin that fits, prioritize it
        // to avoid opening a new bin unnecessarily.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Core Objective: Minimize post_residual while favoring bins that align with future item sizes.
    let mut score = (post_residual as f64) * 1.35;

    // 1. Predictive Lookahead:
    // Penalize "dead-space traps" (residual < next_item) more sharply than the parent.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 245.0 + (next_item_size as f64 * 2.45);
        } else if post_residual >= next_item_size {
            // Reward fits that leave exactly enough space for the next item.
            score -= (post_residual - next_item_size) as f64 * 2.15;
        }
    }

    // 2. Harmonic Fragmentation Avoidance:
    // Stricter penalty for small, unusable fragments (1-20 range).
    if post_residual > 0 && post_residual < 24 {
        score += 190.0 - (post_residual as f64 * 4.2);
    }

    // 3. Dynamic Bin Management:
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Exponentially scale opening new bins relative to current count to force reuse.
            score += 385.0 + (open_bins_count as f64).powf(1.8) * 18.0 + (progress * 150.0);
        } else {
            score = 15.0 + (mean_residual * 0.12);
        }
    } else {
        // 4. Density Balancing & Consolidation:
        // Reward filling bins to capacity (lower residual = higher score).
        score -= (bin_capacity - bin_residual) as f64 * 1.15;

        // Penalize variance from the mean residual to maintain uniform bin growth.
        score += (post_residual as f64 - mean_residual).abs() * 0.95;
    }

    // 5. Global Consolidation:
    // Non-linear penalty on open bin count.
    if open_bins_count > 1 {
        score += (open_bins_count as f64 - 1.0).powf(2.25) * 45.0;
    }

    // 6. Terminal Phase Shift:
    // Aggressive consolidation in the final 15% of the stream.
    if progress > 0.85 {
        score -= (progress - 0.85) * 1100.0;
    } else {
        score -= progress * 40.0;
    }

    // 7. Residual Modulo Bias:
    // Reduced penalty for alignment with powers of 2 (fragmentation reduction).
    let mod_val = post_residual % 16;
    score += (mod_val as f64).min(16.0 - mod_val as f64) * 1.8;

    // 8. Fitting Capacity Bonus:
    // Favor bins that are already under high pressure to finish them off.
    score -= (fitting_bins_count as f64).sqrt() * 12.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base heuristic: Best-Fit (minimize post_residual).
    // We heavily penalize creating small "dead zones" (residuals < 10) 
    // especially as the stream progresses, to prevent fragmentation.
    let mut score = post;

    // Penalty for creating a sliver of space that is hard to fill later.
    if post > 0.0 && post < 15.0 {
        score += (15.0 - post) * 2.5 * (1.0 + progress);
    }

    // Lookahead logic: If the next item is large, prioritize keeping 
    // larger residuals available. If next_item_size is 0 (end of stream), 
    // prioritize packing tighter.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post < next {
            // Cannot fit the next item; penalize this bin choice proportional 
            // to how much it blocks the next item.
            score += (next - post) * 1.5;
        }
    }

    // If this is a new bin (bin_residual == bin_capacity), we add a "startup cost".
    // We only want to open a new bin if the best existing fit is extremely poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin is 50.0.
        // We reduce this cost as the stream progresses to allow for more 
        // flexibility near the end of the packing process.
        score += 50.0 * (1.0 - (progress * 0.5));
    }

    // Encourage using bins that are already partially full to keep the 
    // number of open bins low (Best-Fit-Decreasing style pressure).
    score += (open_bins_count as f64) * 0.5;

    // If this is the only bin that can fit the item, reward it to prevent
    // premature opening of new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: Refined linear cost for residual, favoring tighter fills.
    let mut score = (post_residual as f64) * 1.35;

    // 1. Predictive Lookahead:
    // Strengthened penalty for dead-space traps; enhanced reward for fitting next_item_size.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 260.0 + (next_item_size as f64 * 2.6);
        } else if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 2.35;
        }
    }

    // 2. Harmonic Fragmentation Avoidance:
    // Penalize small fragments more aggressively to prevent bin pollution.
    if post_residual > 0 && post_residual < 40 {
        score += 195.0 - (post_residual as f64 * 4.2);
    }

    // 3. Dynamic Bin Management:
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Force reuse: increase scaling for open_bins_count to prevent early expansion.
            // Increased power factor to discourage opening bins as open_bins_count grows.
            score += 440.0 + (open_bins_count as f64).powf(1.9) * 18.0 + (progress * 170.0);
        } else {
            // Baseline for expansion: keep new bins expensive.
            score = 30.0 + (mean_residual * 0.25);
        }
    } else {
        // 4. Density Balancing:
        // Reward filling bins to capacity to trigger consolidation.
        score -= (bin_capacity - bin_residual) as f64 * 1.25;

        // Penalize deviation from the mean, but attenuated by bin fullness.
        score += ((post_residual as f64 - mean_residual).abs()) * 0.85;
    }

    // 5. Global Consolidation:
    // Increased non-linear penalty on open bin count.
    if open_bins_count > 2 {
        score += (open_bins_count as f64 - 2.0).powf(2.4) * 50.0;
    }

    // 6. Terminal Phase Shift:
    // Accelerate consolidation in the final 25% of the stream.
    if progress > 0.75 {
        score -= (progress - 0.75) * 1400.0;
    } else {
        score -= progress * 85.0;
    }

    // 7. Residual Modulo Bias:
    // Favor residuals that align with common item size patterns (multiples of 10 and 25).
    let mod_val = post_residual % 25;
    score += (mod_val as f64).min(25.0 - mod_val as f64) * 3.2;

    // 8. Fitting Capacity Bonus:
    // Favor bins that are more constrained to increase packing density.
    // Enhanced weight to force consolidation into existing narrow bins.
    score -= (fitting_bins_count as f64) * 1.65;

    score
}
